const artworks = [
{id:'DA-001',title:'Flowers for Forgetting Sorrow',year:2026,frame:'24 × 30 in',image:'assets/da-001.png',alt:'Vermilion flowers with dark, sweeping ink leaves',description:'Vermilion flowers stand against dark ink leaves, their strong contrast giving the painting its brightness and energy. Known in Chinese as wangyouhua, or “flowers for forgetting sorrow,” these blooms express a simple wish. Their vivid color offers a moment of pleasure, a lighter heart, and a little distance from everyday worries.'},
{id:'DA-002',title:'A Fishing Village by the Sea',year:2026,frame:'24 × 30 in',image:'assets/da-002.png',alt:'Shanwei coastal village with waterfront homes, boats, farming stakes, and distant mountains',description:'This coastal landscape depicts Shanwei, Guangdong, the artist’s hometown. Beyond the waterfront homes, rows of stakes mark the village’s coastal farms. Mountains rise in the distance, while boats, nets, and a fisherman bring the scene close to daily life. Ink and pale color capture the quiet rhythm of a community that lives with the sea.',inscription:'Distant mountains hold the green of jade. By the sea, fishing families make their home.'},
{id:'DA-003',title:'Red Plum Blossoms',year:2026,frame:'24 × 30 in',image:'assets/da-003.png',alt:'Abundant red plum blossoms on bold, freely extending ink branches',description:'Painted in a calm, settled state of mind, these red plum blossoms express an enduring warmth of spirit. Abundant flowers bring vitality, while the strong branches suggest conviction and resilience. Their freely extending forms reflect the artist’s wish to remain openhearted and true to himself through life’s many changes.'},
{id:'DA-004',title:'The Path Upward',year:2026,frame:'16 × 20 in',image:'assets/da-004.png',alt:'Stone steps ascending steep cliffs toward a pavilion, with trees and a blue stream below',description:'Stone steps wind between steep cliffs toward a pavilion above. Small figures climb the path as water descends through the rocks, drawing the eye through the landscape in two directions. Spare brushwork and light washes of earth and blue invite a leisurely journey, with time to pause, listen to the stream, and look out across the mountains.'},
{id:'DA-005',title:'In the Humble Administrator’s Garden',year:2026,frame:'16 × 20 in',image:'assets/da-005.png',alt:'Quiet Suzhou garden with an arched bridge, stream, trees, and pavilions',description:'Painted on location in the Humble Administrator’s Garden in Suzhou, this work captures a quiet corner of a historic Chinese garden. Created during the Ming dynasty, the garden brings water, rocks, trees, and pavilions together in views that unfold with each turn of the path. The artist’s relaxed brushwork follows the stream, bridge, and surrounding trees, preserving the pleasure of being there, absorbed in the garden’s quiet.'},
{id:'DA-006',title:'Good Fortune Ahead',year:2022,frame:'12 × 12 in',image:'assets/da-006.png',alt:'A woven basket brimming with red lychees, with calligraphy at the right',description:'Painted at home during the pandemic, this basket of lychees recalls the familiar fruit of the artist’s native Lingnan. Its full, red fruit carries wishes for health, abundance, and brighter days. In the quiet of those confined months, painting offered him a small source of vitality and comfort, and a way to hold hope for life beyond the room.'}
];
const grid=document.querySelector('#art-grid');
artworks.forEach((work,index)=>{
 const button=document.createElement('button');button.type='button';button.className='art-card';button.setAttribute('aria-label',`View ${work.title}, ${work.year}`);
 const stage=document.createElement('div');stage.className='art-stage';const image=document.createElement('img');image.src=work.image;image.alt=work.alt;image.loading='lazy';image.decoding='async';image.width=work.id==='DA-006'?432:512;image.height=work.id==='DA-006'?432:640;stage.append(image);
 const arrow=document.createElement('span');arrow.className='view-arrow';arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');stage.append(arrow);
 const label=document.createElement('div');label.className='art-label';const title=document.createElement('h3');title.textContent=work.title;const year=document.createElement('span');year.textContent=work.year;label.append(title,year);
 const code=document.createElement('p');code.className='art-code';code.textContent=work.id;button.append(stage,label,code);button.addEventListener('click',()=>openArtwork(index));grid.append(button);
});
const dialog=document.querySelector('#art-dialog'),layout=dialog.querySelector('.detail-layout');let active=0,lastFocused=null;
function renderArtwork(index){active=(index+artworks.length)%artworks.length;const work=artworks[active];layout.classList.remove('zoomed');document.querySelector('#zoom-art').setAttribute('aria-label','Enlarge artwork');document.querySelector('.zoom-hint').firstChild.textContent='Look closer ';document.querySelector('#detail-image').src=work.image;document.querySelector('#detail-image').alt=work.alt;document.querySelector('#detail-id').textContent=work.id;document.querySelector('#detail-title').textContent=work.title;document.querySelector('#detail-byline').textContent=`Weibang Yang · 杨位榜 · ${work.year}`;document.querySelector('#detail-description').textContent=work.description;document.querySelector('#detail-frame').textContent=work.frame;document.querySelector('#detail-count').textContent=`${String(active+1).padStart(2,'0')} / 06`;const quote=document.querySelector('#detail-inscription');quote.hidden=!work.inscription;quote.textContent=work.inscription||'';document.querySelector('#detail-inquire').href=`mailto:4415yqc@gmail.com?subject=${encodeURIComponent(`Artwork inquiry: ${work.title} (${work.id})`)}&body=${encodeURIComponent(`Hello,\n\nI’m interested in ${work.title} (${work.year}) by Weibang Yang. Could you tell me more about its availability?\n\nThank you!`)}`;dialog.scrollTop=0;}
function openArtwork(index){lastFocused=document.activeElement;renderArtwork(index);dialog.showModal();document.body.classList.add('modal-open');document.querySelector('#close-dialog').focus();}
function closeArtwork(){dialog.close();}
document.querySelector('#close-dialog').addEventListener('click',closeArtwork);document.querySelector('#close-icon').addEventListener('click',closeArtwork);dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');layout.classList.remove('zoomed');lastFocused?.focus({preventScroll:true});});
document.querySelector('#prev-art').addEventListener('click',()=>renderArtwork(active-1));document.querySelector('#next-art').addEventListener('click',()=>renderArtwork(active+1));
dialog.addEventListener('keydown',event=>{if(event.key==='ArrowRight'){event.preventDefault();renderArtwork(active+1)}if(event.key==='ArrowLeft'){event.preventDefault();renderArtwork(active-1)}});
document.querySelector('#zoom-art').addEventListener('click',()=>{const zoomed=layout.classList.toggle('zoomed');document.querySelector('#zoom-art').setAttribute('aria-label',zoomed?'Return to artwork details':'Enlarge artwork');document.querySelector('.zoom-hint').firstChild.textContent=zoomed?'Return to details ':'Look closer ';dialog.scrollTop=0;});
